import unittest
from gradebook import average, letter, top_n


class Regression(unittest.TestCase):
    def test_average(self):
        self.assertEqual(average([80, 90, 100]), 90)

    def test_just_below_a_boundary_stays_lower(self):
        self.assertEqual(letter(89.9), "B")
        self.assertEqual(letter(59.9), "F")
        self.assertEqual(letter(95), "A")

    def test_ties_are_listed_alphabetically(self):
        scores = {"b": 70, "a": 70, "c": 50}
        self.assertEqual(top_n(scores, 2), ["a", "b"])

    def test_n_larger_than_the_class(self):
        self.assertEqual(top_n({"a": 1}, 5), ["a"])

